class TaUeServerStartFailure(Exception):
    pass


def retry(attempts):
    """
    Decorator to retry function call
    :param attempts:
    :return:
    """
    def decorator(func):
        """Decorator"""
        def wrapper(*args, **kwargs):
            """Wrapper"""
            counter = 0
            logger = logging.getLogger('ute_ue.UexConnection')
            while counter <= attempts:
                counter += 1
                try:
                    return func(*args, **kwargs)
                except CommandFailure as err:
                    _decorator_exception(logger, func, err, counter, attempts)

        return wrapper
    return decorator


def _decorator_exception(logger, func, err, counter, attempts):
    if counter >= attempts:
        logger.debug("Method {} {}".format(func.__name__, 'finally failed.'))
        raise err
    else:
        logger.debug("Method {} {}".format(func.__name__, 'failed. Retry in 5 sec...'))
        sleep(5)


@six.add_metaclass(Singleton)
class TaUeServer:
    def __init__(self):
        """Elixir server remote start"""
        self.load_config()

    def start(self):
        """Use moler to start 'ta_ue_server' script on RTG Workstation"""
        self.rtg_ws._cmdnames_available_in_state['UNIX_LOCAL']['iex -S rez'] = 'ta_ue_plugin_rtg.moler_cmd.iexrez.IexRez'
        if isinstance(self.rtg_ws, UnixRemote):
            self.rtg_ws._cmdnames_available_in_state['UNIX_REMOTE']['iex -S rez'] = 'ta_ue_plugin_rtg.moler_cmd.mix.iexrez.IexRez'
            self.rtg_ws.goto_state(state="UNIX_REMOTE")

        cd_path = self._check_uex_exs_config_dir()
        self._run_iex_s_rez(cd_path)

    def load_config(self):
        """Load moler configuration of the RTGWS device and if doesn't exist use UnixLocal"""
        device_configuration = self._get_device_config()

        # align robot logdir with moler logdir
        robot_logs_dir = self._get_robot_logs_dir()
        if robot_logs_dir:         # test was run through robot framework
            self.logdir = robot_logs_dir
            load_logger_from_config({'LOGGER': {'PATH': robot_logs_dir}})
        else:                      # test was run through pyhton script
            self.logdir = os.getcwd()

        load_device_from_config(config=device_configuration)
        try:
            self.rtg_ws = DeviceFactory.get_device(name="RTGWS")
        except DeviceFailure as err:
            raise InvalidConfigurationContent(err)
        self._set_rtgws_connection_parameters(device_configuration)

    def get_hostname(self):
        """Return server_hostname"""
        return self.server_hostname

    def get_logdir(self):
        """Return logdir"""
        return self.logdir

    @retry(attempts=5)
    def _run_iex_s_rez(self, cd_path):
        cd_to_uex_path = self.rtg_ws.get_cmd(cmd_name="cd", cmd_params={"path": cd_path})
        cd_to_uex_path()
        iex_s_rez = self.rtg_ws.get_cmd(cmd_name="iex -S rez", cmd_params={"app": "ta_ue_plugin_rtg_server"})
        try:
            iex_s_rez(timeout=120)
        except CommandFailure as err:
            if "UEx app is already started" in str(err):
                raise TaUeServerStartFailure("Cannot start ta_ue_server, UEx node is already running. "
                                             "Please close UEx or run 'ps aux | grep beam | awk '{print $2}' | xargs kill'")
            else:
                raise err

    def _check_uex_exs_config_dir(self):
        platform = get_platform()
        paths = ["/opt/{}/etc/uex/".format(platform), "/opt/{}/lib/uex/".format(platform)]
        working_dir = None
        for path in paths:
            ls_uex_exs = self.rtg_ws.get_cmd(cmd_name="ls", cmd_params={"path": path + "uex.exs"})
            try:
                ls_uex_exs()
            except CommandFailure as err:
                if 'No such file or directory' in str(err):
                    continue
                else:
                    raise err
            working_dir = path
        if working_dir is None:
            raise TaUeServerStartFailure("No uex.exs config file not found. Please reinstall RTG package")
        return working_dir

    @staticmethod
    def _get_robot_logs_dir():
        if logging.getLogger('ute_ue').handlers and isinstance(logging.getLogger('ute_ue').handlers[0], logging.FileHandler):
            return os.path.dirname(logging.getLogger('ute_ue').handlers[0].baseFilename)

    def _set_rtgws_connection_parameters(self, device_configuration):
        """Set appropriate proxy_pc and server_hostname based on moler RTGWS device class"""
        try:
            if isinstance(self.rtg_ws, UnixRemote):
                self.server_hostname =\
                    device_configuration['DEVICES']['RTGWS']['CONNECTION_HOPS']['UNIX_LOCAL']['UNIX_REMOTE']['command_params']['host']
            elif isinstance(self.rtg_ws, UnixLocal):
                self.server_hostname = '127.0.0.1'
            else:
                raise InvalidConfigurationContent
        except KeyError as err:
            raise InvalidConfigurationContent(err)

    @staticmethod
    def _is_rtgws_configured(device_configuration):
        try:
            return 'RTGWS' in device_configuration['DEVICES']
        except KeyError:
            return False

    @staticmethod
    def _get_device_config():
        # temporarly disable config logger to avoid warnings about empty config
        config_logger = logging.getLogger('al.config')
        old_val = config_logger.disabled
        config_logger.disabled = True
        config = Config().get_config()
        config_logger.disabled = old_val

        try:
            rtg_ue_pool_config = config['UE_POOLS']['RtgUePool']
        except (KeyError, TypeError):
            rtg_ue_pool_config = {}

        if 'config_file_path' in rtg_ue_pool_config:
            config_file_abspath = Config().resolve_config_abspath(rtg_ue_pool_config['config_file_path'])
            device_configuration = Config().read_yaml_configfile(config_file_abspath)
        elif 'inline_config' in rtg_ue_pool_config:
            device_configuration = rtg_ue_pool_config['inline_config']
        else:
            device_configuration = {}

        if TaUeServer._is_rtgws_configured(device_configuration):
            return device_configuration
        else:
            return {'DEVICES':
                    {'RTGWS': {'DEVICE_CLASS': 'moler.device.unixlocal.UnixLocal'},
                     'CREATE_AT_STARTUP': False,
                     'DEFAULT_CONNECTION': {'CONNECTION_DESC': {'io_type': 'terminal', 'variant': 'threaded'}}}}


@six.add_metaclass(Singleton)
class UexConnection:
    def __init__(self):
        """Connection to UEx JSON-RPC Server"""
        self.logger = None
        self._set_logger()
        try:
            TaUeServer().start()
        except TaUeServerStartFailure as err:
            self.logger.error(str(err))

        host = TaUeServer().get_hostname()
        tcp_conn = TCPTransportMedium(port=8000, host=host, logger=self.logger)
        self.rpc_conn = JsonRpcClient("conn1", tcp_conn)
        self.rpc_conn._activated_transport_encoding = "netstring"
        self._open_rcp_conn()
        self._verify_server_version()
        self._align_server_logdir_with_robot_logdir()
        self.ta_messaging_backend_started = False
        ta_messaging_backend().register('ta_ue_plugin_rtg_server', lambda: host, self._start_ta_messaging_backend)

    def _set_logger(self):
        logger.create_logger('ute_ue.UexConnection', 'ute_ue.uex_connection.log')
        self.logger = logging.getLogger('ute_ue.UexConnection')
        cfh = logging.StreamHandler()
        cfh.setLevel(level=30)
        self.logger.addHandler(cfh)

    def _verify_server_version(self):
        try:
            server_version = self.rpc_conn.call("test_version", "")
        except ErrJsonRpcError as err:
            server_resp = json.loads(json.dumps(err.err))
            if 'resp' in server_resp:
                server_resp = server_resp['resp']['error']
            err_message = server_resp['message']
            err_code = server_resp['code']
            if err_code == -32601:
                self.logger.warning("JSON-RPC Server is an old version"
                                    "please use 'rtg-update' to install the latest RTG build")
            else:
                error_message = "JSON-RPC Server Connection test failed. Error: {}.  Code: {}".format(err_message, err_code)
                self.logger.error(error_message)
        else:
            if plugin_version != server_version:
                self.logger.warning("Plugin (v{}) and server (v{}) versions don't match.".format(plugin_version, server_version) + ""
                                    " Some features may not work, please update ta_ue_plugin_rtg and RTG build to the latest version")
            else:
                self.logger.info("Plugin's and server's versions match")

    def _start_ta_messaging_backend(self, port):
        if not self.ta_messaging_backend_started:
            self.rpc_conn.call("start_ta_messaging_backend", port)
            self.ta_messaging_backend_started = True

    def _align_server_logdir_with_robot_logdir(self):
        try:
            if TaUeServer().get_hostname() in ['127.0.0.1', 'localhost']:
                self.rpc_conn.call("set_logdir", TaUeServer().get_logdir())
            else:
                remote_logdir = self.rpc_conn.call("set_logdir", "./")
                # TODO copy logs using scp after execution?
                self.logger.info("Cannot save test logs inside {}, ta_ue server is running on a remote machine"
                                 " RTG logs will be stored inside {}:{} instead".format(TaUeServer().get_logdir(),
                                                                                        TaUeServer().get_hostname(), remote_logdir))
        except ErrJsonRpcError as err:
            server_resp = json.loads(json.dumps(err.err))
            if 'resp' in server_resp:
                server_resp = server_resp['resp']['error']
            err_message = server_resp['message']
            # err_code = server_resp['code']
            self.logger.error(err_message)

    def _open_rcp_conn(self):
        try:
            self.rpc_conn.open_connection()
        except Exception:
            self.logger.error("Failed to connect to JSON-RPC server. ta_ue_server might not have been started. "
                              "Chceck moler.RTGWS.log for details.\n")
            raise
